#include "core.h"
#include "settings_logic.h"
#include <iostream>
using namespace pet;
static int checks=0;
static void check(bool value,const char*message){++checks;if(!value)throw std::runtime_error(message);}
static Config reload(const Config&source,bool update){Config restored;restored.load(Json::parse(source.json().dump()),update);return restored;}
int main(){try{
 for(bool writable:{false,true})for(bool portable:{false,true})for(bool local:{false,true})for(bool newer:{false,true}){auto paths=chooseSettings(portable,local,writable,newer);check(paths.write==(writable?SettingsFile::Portable:SettingsFile::Local),"write permission changes only the destination");auto expected=local&&(!portable||newer)?SettingsFile::Local:portable?SettingsFile::Portable:SettingsFile::None;check(paths.read==expected,"existing/newer user settings are read before first-run defaults");check((paths.alternate!=SettingsFile::None)==(portable&&local),"both existing sources remain available for corrupt-primary recovery");}
 check(chooseSettings(false,true,true).read==SettingsFile::Local,"new writable version directory reads previous LocalAppData recovery instead of losing names");check(chooseSettings(true,false,false).read==SettingsFile::Portable,"read-only old portable settings are loaded before migrating writes");
 Config c;c.enableTimerModes();c.scale=175;c.opacity=55;c.top=false;c.pass=true;c.showNameplate=true;c.x=-1200;c.y=45;c.dialogueEditorWidth=980;c.dialogueEditorHeight=700;
 for(int p:{0,1,3,4,5,6})for(int coat=0;coat<builtinCoats(p);++coat){check(c.selectBuiltin(p,coat),"appearance identity remains selectable");c.rename("名🐾"+std::to_string(builtinIdentity(p,coat)));}
 for(int slot=0;slot<3;++slot){auto&profile=c.profiles[size_t(slot)];profile.files["idle"]=std::string(64,char('a'+slot))+".gif";profile.files["heart"]=std::string(64,char('d'+slot))+".png";profile.fileLabels["idle"]="來源 日本語.gif";profile.setDialogue(Language::JaJP,"general",Json::Array{"名前を覚えてるよ"});check(c.selectCustom(slot),"custom slot ready");c.rename("自訂🐾"+std::to_string(slot));}
 const auto profiles=c.json()["customProfiles"].dump(),tasks=c.timers.json().dump();
 for(bool update:{false,true})for(int language=0;language<3;++language){Config restored=reload(c,update);restored.setLanguage(Language(language));for(int p:{0,1,3,4,5,6})for(int coat=0;coat<builtinCoats(p);++coat){restored.selectBuiltin(p,coat);check(restored.name=="名🐾"+std::to_string(builtinIdentity(p,coat)),"all 22 independent names survive normal/update restart and every language");auto checkpoint=reload(restored,update);check(checkpoint.name==restored.name,"name persists even when each appearance is the active startup identity");}for(int slot=0;slot<3;++slot){restored.selectCustom(slot);check(restored.name=="自訂🐾"+std::to_string(slot),"all three custom names remain independent through language and restart");}check(restored.json()["customProfiles"].dump()==profiles&&restored.timers.json().dump()==tasks,"files, original filenames, dialogue and three timer settings remain untouched");check(restored.scale==175&&restored.opacity==55&&!restored.top&&restored.pass&&restored.x==-1200&&restored.dialogueEditorWidth==980,"desktop/editor preferences are unchanged by name persistence");}
 for(int p:{0,1,3,4,5,6})for(int coat=0;coat<builtinCoats(p);++coat)for(int partial:{0,1,22}){Json old;old["pet"]=p;old["coat"]=coat;old["name"]="舊名🐾";old["builtinName"]="舊名🐾";old["builtinNames"]=Json::Array(size_t(partial),Json(""));Config migrated;migrated.load(old,true);check(migrated.name=="舊名🐾","legacy custom name is recovered from empty/partial indexed arrays");auto fixed=reload(migrated,true);fixed.setLanguage(Language::JaJP);check(fixed.name=="舊名🐾","migrated name becomes a persistent independent override");fixed.resetName();auto reset=fixed.json();reset["name"]="舊名🐾";reset["builtinName"]="舊名🐾";Config explicitReset;explicitReset.load(reset,true);check(explicitReset.effectiveName()==tr(TextId(int(TextId::PetName0)+builtinIdentity(p,coat)),Language::JaJP),"new name schema makes an explicit reset authoritative over stale legacy aliases");}
 for(int language=0;language<3;++language){Config defaults;defaults.setLanguage(Language(language));auto old=defaults.json();std::get<Json::Object>(old.v).erase("nameSchema");Config migrated;migrated.load(old,true);migrated.setLanguage(Language((language+1)%3));check(migrated.name==tr(TextId::PetName0,Language((language+1)%3)),"old empty indexed slots with localized default aliases remain defaults");}
 Json conflicting;conflicting["pet"]=5;conflicting["coat"]=1;conflicting["name"]="舊名";Json::Array overrides(22,Json(""));overrides[0]="橘寶";overrides[17]="正名";conflicting["builtinNames"]=overrides;Config authoritative;authoritative.load(conflicting,true);check(authoritative.name=="正名"&&authoritative.builtinNames[0]=="橘寶","existing independent overrides win over a stale shared alias and preserve siblings");
 Config pin;pin.rename(pin.name);auto saved=reload(pin,true);saved.setLanguage(Language::EnUS);check(saved.name=="小橘","explicitly typing a default-looking name remains a custom name");saved.resetName();saved=reload(saved,true);saved.setLanguage(Language::EnUS);check(saved.name==tr(TextId::PetName0,Language::EnUS),"manual reset restores language-following defaults");
 c.selectCustom(0);c.rename("Custom pet 1");auto custom=reload(c,true);custom.setLanguage(Language::JaJP);check(custom.name=="Custom pet 1","custom name equal to another language default is never guessed or translated");custom.resetName();custom=reload(custom,true);custom.setLanguage(Language::JaJP);check(custom.name==formatText(TextId::NameCustom,{"1"},Language::JaJP),"custom reset retains explicit default marker");check(custom.profiles[1].name=="自訂🐾1","reset never affects sibling profiles");
 Json oldShared;oldShared["pet"]=6;oldShared["coat"]=2;oldShared["name"]="很久以前的名稱不截斷";Config legacy;legacy.load(oldShared,true);check(legacy.name==oldShared["name"].str(),"pre-index legacy names retain their original text within existing storage limits");bool rejected=false;try{legacy.rename("中文日文超過六個字");}catch(...){rejected=true;}check(rejected&&legacy.name==oldShared["name"].str(),"new edits retain the 12-unit limit without erasing the previous name");
 check(!packagePath("config.json")&&!packagePath("pet-names.json"),"name persistence does not enlarge update package whitelist");
 std::cout<<"PASS: "<<checks<<" v1.5.3 name checks; all 22+3 names, restart/update, language/reset, legacy migration and settings-source selection\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<" after "<<checks<<" checks\n";return 1;}}
